    'pageDescription.detail': { ar: 'معلومات مفصلة عن أحد إعلانات StudentHub. جميع المحتويات بيانات تجريبية خيالية.', en: 'Detailed information about a StudentHub listing. All content is fictional demo data.' },
    'intro.brand': { ar: 'StudentHub', en: 'StudentHub' },
    'pageDescription.about': { ar: 'تعرّف على StudentHub ورسالتنا ورؤيتنا ومبادئنا الطلابية.', en: 'Learn about StudentHub, our mission, our vision and our student-focused values.' },
    'about.heroEyebrow': { ar: 'عن StudentHub', en: 'About StudentHub' },
    'about.heroTitle': { ar: 'حياة جامعية أسهل، تبدأ من هنا', en: 'A simpler university journey starts here' },
    'about.heroText': { ar: 'منصة طلابية تجمع المعلومات والخدمات والفرص المفيدة في مكان واحد.', en: 'A student-focused platform bringing useful information, services and opportunities together in one place.' },
    'about.aboutTitle': { ar: 'من نحن؟', en: 'About us' },
    'about.aboutText': { ar: 'نحن مجموعة من طلاب علوم الحاسوب الطموحين. أطلقنا StudentHub انطلاقًا من إيماننا بأن الحياة الجامعية ينبغي أن تكون أسهل تنظيمًا، وأن الوصول إلى المعلومات والخدمات المفيدة لا ينبغي أن يكون معقدًا بلا داعٍ.', en: 'We are a group of ambitious Computer Science students who created StudentHub with a simple belief: university life should be easier to navigate, and finding useful information and services should not be unnecessarily complicated.' },
    'about.missionTitle': { ar: 'رسالتنا', en: 'Our mission' },
    'about.missionText': { ar: 'نسعى إلى مساعدة الطلاب على توفير الوقت والجهد بجمع المعلومات والخدمات والفرص الطلابية المفيدة في مكان واحد، ليتمكنوا من التركيز أكثر على تعليمهم ومستقبلهم.', en: 'Our mission is to help students save time and effort by bringing useful information, services, and student opportunities together in one place, allowing them to focus more on their education and future.' },
    'about.whyTitle': { ar: 'لماذا أنشأنا StudentHub؟', en: 'Why StudentHub?' },
    'about.whyText': { ar: 'قد يحتاج الطالب إلى سكن مناسب، أو وسيلة مواصلات، أو خصم طلابي، أو اشتراك رقمي، أو برنامج يساعده في دراسته. ومع ذلك، قد يصعب العثور على معلومات موثوقة حول هذه الخدمات ومعرفة كيفية الاستفادة من الفرص المتاحة.', en: 'Students often need suitable housing, transportation, student discounts, digital subscriptions, or software for their studies. Yet finding reliable information about these services and learning how to access available opportunities can be difficult.' },
    'about.whyText2': { ar: 'لذلك، نعمل على جعل اكتشاف هذه الموارد والوصول إليها أسهل من خلال منصة عملية واحدة.', en: 'StudentHub aims to make these resources easier to discover and access through one practical platform.' },
    'about.valuesTitle': { ar: 'قيمنا', en: 'Our values' },
    'about.valuesText': { ar: 'StudentHub مشروع طلابي غير ربحي، نطوره بجهود فريقنا وإمكاناتنا. هدفنا تقديم فائدة حقيقية للمجتمع الطلابي، ولا نعتمد على الإعلانات لتحقيق الأرباح. ونسعى إلى تحسين المنصة بما يلبي احتياجات الطلاب.', en: 'StudentHub is a non-commercial student project developed through our team’s own efforts and resources. Our goal is to provide genuine value to the student community. We do not rely on advertisements for revenue, and we aim to improve the platform according to students’ needs.' },
    'about.visionTitle': { ar: 'رؤيتنا', en: 'Our vision' },
    'about.visionText': { ar: 'نطمح إلى أن يكون StudentHub رفيقًا مفيدًا للطالب طوال رحلته الجامعية. ونواصل تطويره استنادًا إلى احتياجات الطلاب وملاحظاتهم، لمساعدتهم على اكتشاف المزيد من الفرص والاستفادة منها.', en: 'Our vision is to make StudentHub a useful companion throughout university life, continuously improving it based on students’ needs and feedback so they can discover and benefit from more opportunities.' },
    'about.closing': { ar: 'StudentHub — صُنع بجهود طلابية، من أجل الطلاب.', en: 'StudentHub — Built by students, for students.' },
    'about.acknowledgementsTitle': { ar: 'شكر وتقدير', en: 'Acknowledgements' },
    'about.acknowledgementYoussef': { ar: 'شكرًا ليوسف على أفكاره لتحسين تجربة المستخدم.', en: 'Thanks to Youssef for his ideas on improving the user experience.' },
    'about.acknowledgementJwan': { ar: 'شكرًا لجوان على أفكاره المقترحة للأقسام.', en: 'Thanks to Jwan for the suggested section ideas.' },
    'about.acknowledgementG': { ar: 'شكرًا لـ G على الشعار وأفكار التصميم.', en: 'Thanks to G for the logo and design ideas.' },
    'about.partnershipTitle': { ar: 'هل تملك مشروعًا يخدم الطلاب؟', en: 'Do you run a business that serves students?' },
    'about.partnershipSubtitle': { ar: 'كن جزءًا من مجتمع StudentHub', en: 'Be part of the StudentHub community' },
    'about.partnershipIntro': { ar: 'هل تملك متجرًا، أو مكتبة، أو مطعمًا، أو مقهى، أو مركزًا تدريبيًا، وتريد أن تصل خدماتك وعروضك إلى الطلاب؟', en: 'Do you run a shop, bookstore, restaurant, cafe, or training center and want students to discover your services and offers?' },
    'about.partnershipDescription': { ar: 'يسعدنا أن نتعرف عليك! يتيح StudentHub لأصحاب المشاريع فرصة التواصل معنا للنظر في إمكانية إضافة مشاريعهم إلى المنصة، وتعريف الطلاب بخدماتهم والعروض التي يقدمونها.', en: 'We would be glad to hear from you. StudentHub gives business owners a way to contact our team so we can consider listing their business and introducing students to their services and offers.' },
    'about.partnershipClosing': { ar: 'معًا، نجعل الحياة الجامعية أسهل وأكثر فائدة.', en: 'Together, we can make university life easier and more rewarding.' },
    'about.partnershipCta': { ar: 'تواصل معنا للانضمام', en: 'Contact us to join' },
    'about.partnershipReviewNote': { ar: 'تخضع طلبات الانضمام للمراجعة، ولا يعني إرسال الطلب قبول المشروع أو إدراجه تلقائيًا.', en: 'All requests are reviewed. Sending an inquiry does not guarantee acceptance or automatic listing.' },
